package com.enfec.one.asset.workflow;
import jakarta.persistence.*; import java.time.*; import java.util.UUID;
@Entity @Table(name="asset_reservations") public class AssetReservation { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="request_id",nullable=false) private UUID requestId; @Column(name="asset_id",nullable=false) private UUID assetId; @Column(name="reserved_for",nullable=false,length=150) private String reservedFor; @Column(nullable=false,length=20) private String status="RESERVED"; @Column(name="reserved_at",nullable=false) private OffsetDateTime reservedAt; @Column(name="released_at") private OffsetDateTime releasedAt; protected AssetReservation(){} public AssetReservation(UUID r,UUID a,String f){requestId=r;assetId=a;reservedFor=f;reservedAt=OffsetDateTime.now(ZoneOffset.UTC);} public void allocate(){status="ALLOCATED";} public void release(){status="RELEASED";releasedAt=OffsetDateTime.now(ZoneOffset.UTC);} public UUID getId(){return id;} public UUID getRequestId(){return requestId;} public UUID getAssetId(){return assetId;} public String getReservedFor(){return reservedFor;} public String getStatus(){return status;} public OffsetDateTime getReservedAt(){return reservedAt;} }
